message.content:
{
  "description": "The creature is depicted in side profile facing to the right, standing upright on two hind legs with its torso raised. It has the head and mane of a large feline at the front top, a spotted feline body and hindquarters in the middle and rear, and two large outstretched feathered wings attached at the shoulder region on either side of the body. The overall coloration is tan and light brown with darker brown spots and feather patterning, and a long spotted tail with a dark tuft curves out from the rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a lion-like head with a broad muzzle, dark pinkish-brown nose, white chin and lower lip, visible whisker pores, a yellow eye with a dark pupil looking to the right, and a slightly open mouth",
      "where": "at the top front of the body, above the mane and chest"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears with short fur, light brown on the outside and darker inside, with the right ear more visible than the left",
      "where": "on top of the head, partly embedded in the mane"
    },
    {
      "part": "mane",
      "looks_like": "thick, shaggy, layered hair in shades of light tan to medium brown, with longer strands around the neck and shorter on the crown",
      "where": "encircling the head, neck, and extending down to the upper chest"
    },
    {
      "part": "legs",
      "looks_like": "two muscular hind legs with spotted tan fur, bent at the knee and hock joints in a standing upright posture",
      "where": "extending downward from the lower torso to the ground, one slightly forward of the other"
    },
    {
      "part": "feet",
      "looks_like": "two large feline paws with rounded toe pads, short claws, and spotted fur on top, light-colored on the soles",
      "where": "at the bottom ends of the two hind legs, flat on the ground"
    },
    {
      "part": "tail",
      "looks_like": "a long slender tail covered in small dark spots on tan fur, ending in a bushy dark brown to black tuft, curved into a hook shape",
      "where": "extending from the rear of the hindquarters, curving down and then up at the tip to the left side of the image"
    },
    {
      "part": "wings",
      "looks_like": "two large broad wings with layered feathers, light tan and golden-brown on the upper coverts and darker brown and gray-brown on the flight feathers with dark tips",
      "where": "attached at the shoulder area on the left and right sides of the upper body, spread outward and slightly upward"
    },
    {
      "part": "feathers",
      "looks_like": "dense overlapping leaf-shaped feathers in tan, golden-brown and dark brown, with darker tips on the chest and lighter edges on the wings",
      "where": "covering both wings entirely and the front of the neck and chest from the mane down to the mid-torso"
    },
    {
      "part": "markings",
      "looks_like": "numerous dark brown to black rosette spots with lighter centers, varying in size, on a tan background",
      "where": "covering the torso, sides, hind legs, and tail, becoming smaller and more solid on the lower legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "lion",
    "leopard",
    "eagle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0
}
